#include "../charge_compiler/json.hpp"
#include <algorithm>
#include <charconv>
#include <complex>
#include <cctype>
#include <fstream>
#include <sstream>

using Row=std::vector<double>;
std::string lower(std::string s){for(char&c:s)c=char(std::tolower(static_cast<unsigned char>(c)));return s;}
std::vector<std::string> words(const std::string&s){std::istringstream in(s);std::vector<std::string> out;std::string word;while(in>>word)out.push_back(lower(word));return out;}
Row numbers(const std::string&s){Row row;const char*p=s.data(),*end=p+s.size();while(p!=end){while(p!=end&&std::isspace(static_cast<unsigned char>(*p)))++p;if(p==end)break;const char*q=p;while(q!=end&&!std::isspace(static_cast<unsigned char>(*q)))++q;double x=0;auto parsed=std::from_chars(p,q,x);require(parsed.ec==std::errc{}&&parsed.ptr==q&&std::isfinite(x),"finite exact numeric token required");row.push_back(x);p=q;}return row;}
std::vector<Row> read(const std::string&path,const std::vector<std::string>&header,bool native,size_t expected){std::ifstream in(path);require(bool(in),"response file readable");std::string line;require(bool(std::getline(in,line)),"response header required");require(words(line)==header,"named terminal response header differs from declared profile/bias/excitation order");std::vector<Row> rows;bool footer=false;while(std::getline(in,line)){if(line.find_first_not_of(" \t\r\n")==std::string::npos)continue;if(native&&line.find("End of Xyce(TM) Simulation")!=std::string::npos){require(!footer,"unique native terminal marker");footer=true;continue;}require(!footer,"data after native terminal marker");Row row=numbers(line);require(row.size()==header.size(),"exact response column count");if(native)require(row[0]==double(rows.size()),"consecutive native row index");rows.push_back(std::move(row));}require(rows.size()==expected&&(!native||footer),"complete exact response sweep required");return rows;}
struct Fixture{int profile,drain,body,gate,excitation;std::string name;};
std::vector<Fixture> fixtures(int start,int count,bool ac){std::vector<Fixture> out;for(int p=start;p<start+count;++p)for(int d=0;d<3;++d)for(int b=0;b<2;++b)for(int g=0;g<(ac?3:1);++g)for(int e=0;e<(ac?3:1);++e)out.push_back({p,d,b,g,e,"p"+std::to_string(p)+"d"+std::to_string(d)+"b"+std::to_string(b)+"g"+std::to_string(g)+"e"+std::to_string(e)});return out;}
std::vector<std::string> header(const std::vector<Fixture>&rows,bool ac,bool native){std::vector<std::string> out=native?std::vector<std::string>{"index",ac?"freq":"v(ctrl)"}:ac?std::vector<std::string>{"frequency"}:std::vector<std::string>{"v-sweep","v(ctrl)"};for(const auto&f:rows)for(char t:std::string("dgsb")){std::string source="v"+std::string(1,t)+f.name;if(!ac)out.push_back("i("+source+")");else if(native){out.push_back("ir("+source+")");out.push_back("ii("+source+")");}else{out.push_back("real(i("+source+"))");out.push_back("imag(i("+source+"))");}}return out;}
Json analyse(const Json&cfg,bool ac){int start=cfg.at("profile_start").integer(),count=cfg.at("profile_count").integer();auto f=fixtures(start,count,ac);const auto&spec=cfg.at(ac?"ac":"dc");auto ng=read(spec.at("reference").str(),header(f,ac,false),false,ac?3:7),xy=read(spec.at("native").str(),header(f,ac,true),true,ac?2:7);if(ac){require(ng[0][0]==1e6&&ng[1][0]==4e8&&ng[2][0]==7.99e8,"reference three-frequency grid");ng.resize(2);}long long comparisons=0,exceedances=0;double max_abs=-1,max_scaled=0;Json worst=Json::object();Json profiles=Json::object();double kcl_ng=0,kcl_xy=0;long long kcl_ng_bad=0,kcl_xy_bad=0;
 for(size_t r=0;r<xy.size();++r){double coordinate=ac?ng[r][0]:ng[r][1],expected=ac?(r==0?1e6:4e8):double(r)*.3;auto aligned=[&](double x){return std::abs(x-expected)<=1e-12*std::max(1.,std::abs(expected));};require(aligned(coordinate)&&aligned(xy[r][1])&&(ac||aligned(ng[r][0])),"independent DC/AC sweep coordinates");size_t width=ac?8:4,offset=ac?1:2;
  for(size_t i=0;i<f.size();++i){std::complex<double> sum_ng=0,sum_xy=0;double l1_ng=0,l1_xy=0;std::string key=std::to_string(f[i].profile);if(!profiles.obj().contains(key)){Json s=Json::object();s["comparisons"]=0LL;s["maximum_absolute_current_difference_A"]=0.;s["diagnostic_numeric_screen_exceedances"]=0LL;profiles[key]=s;}
   for(size_t e=0;e<4;++e){size_t k=i*width+e*(ac?2:1);std::complex<double> left(ng[r][offset+k],ac?ng[r][offset+k+1]:0),right(xy[r][2+k],ac?xy[r][2+k+1]:0);double delta=std::abs(left-right),scale=std::max({std::abs(left),std::abs(right),1e-18}),scaled=delta/scale;bool bad=delta>1e-15+1e-8*std::max(std::abs(left),std::abs(right));++comparisons;exceedances+=bad;max_scaled=std::max(max_scaled,scaled);auto&s=profiles[key];s["comparisons"]=s.at("comparisons").integer()+1;s["diagnostic_numeric_screen_exceedances"]=s.at("diagnostic_numeric_screen_exceedances").integer()+int(bad);s["maximum_absolute_current_difference_A"]=std::max(s.at("maximum_absolute_current_difference_A").num(),delta);sum_ng+=left;sum_xy+=right;l1_ng+=std::abs(left);l1_xy+=std::abs(right);
    if(delta>max_abs){max_abs=delta;worst["profile_id"]=f[i].profile;worst["coordinate"]=coordinate;worst["drain_source_bias_magnitude_v"]=.9*f[i].drain;worst["reverse_body_bias_magnitude_v"]=.2*f[i].body;worst["gate_source_bias_magnitude_v"]=ac?Json(.9*f[i].gate):Json();worst["AC_excitation"]=ac?Json(std::vector<std::string>{"gate","drain","bulk"}[f[i].excitation]):Json();worst["electrode"]=std::vector<std::string>{"drain","gate","source","bulk"}[e];Json l=Json::array(),v=Json::array();l.push(left.real());l.push(left.imag());v.push(right.real());v.push(right.imag());worst["reference_A"]=l;worst["native_A"]=v;worst["scaled_delta"]=scaled;}
   }double a=std::abs(sum_ng),b=std::abs(sum_xy);kcl_ng=std::max(kcl_ng,a);kcl_xy=std::max(kcl_xy,b);kcl_ng_bad+=a>1e-15+1e-8*l1_ng;kcl_xy_bad+=b>1e-15+1e-8*l1_xy;
  }
 }
 Json result=Json::object();result["terminal_response_comparisons"]=comparisons;result["maximum_absolute_current_difference_A"]=max_abs;result["maximum_scaled_current_difference"]=max_scaled;result["diagnostic_numeric_screen_exceedances"]=exceedances;result["worst_absolute_current_difference"]=worst;result["profiles"]=profiles;result["maximum_reference_terminal_KCL_A"]=kcl_ng;result["maximum_native_terminal_KCL_A"]=kcl_xy;result["reference_terminal_KCL_screen_exceedances"]=kcl_ng_bad;result["native_terminal_KCL_screen_exceedances"]=kcl_xy_bad;return result;
}
int main(int argc,char**argv){try{require(argc==2,"one batch audit configuration required");Json cfg=Json::read(argv[1]);auto start=cfg.at("profile_start").integer(),count=cfg.at("profile_count").integer();require(start>=0&&start+count<=476&&count>0&&count<=16,"bounded declared profile batch");Json out=Json::object();out["dc"]=analyse(cfg,false);out["ac"]=analyse(cfg,true);out["named_terminal_headers_verified"]=true;out["independent_sweep_coordinates_verified"]=true;out["release_qualified"]=false;std::cout<<out.dump()<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
